enum DateTime64 {
    Nat,
    Valid(i64),
}

fn isnat(x: Vec<DateTime64>) -> Vec<bool> {
    let mut res = Vec::with_capacity(x.len());
    for dt in x {
        match dt {
            DateTime64::Nat       => res.push(true),
            DateTime64::Valid(_)  => res.push(false),
        }
    }
    res
}

